var e=[{id:"goldbug",name:"The Gilded Scarab",species:"Chrysina resplendens",plan:"scarab",palette:["#f6d044","#b8860b","#5c4409","#fff3bf"],hint:"Raise your hand until somebody objects.",where:"The raise-hand control, on the third raise.",fact:"Its shell is a stack of chitin layers that reflects both circular polarisations, which is why it looks like poured metal and why almost nothing else in nature does.",repeat:3},{id:"jewel",name:"The Jewel Beetle",species:"Sternocera aequisignata",plan:"jewel",palette:["#1f9e6e","#0d5f43","#0a3327","#ffd76a"],hint:"Keep pressing the thing that is a picture of wifi.",where:"The system tray on the shared desktop.",fact:"Its wing cases keep their colour for centuries and were sewn onto textiles as beetlewing embroidery long before anyone made a dye that lasted as long.",repeat:3},{id:"birdwing",name:"The Birdwing",species:"Ornithoptera priamus",plan:"birdwing",palette:["#25c07a","#0e6b45","#171a1c","#8ff0c0"],hint:"React. Then react again. Then again.",where:"The reaction tray in the control bar.",fact:"The green is structural rather than pigment, so a wing that is emerald from above is brown from the side. One of the largest butterflies alive, and the female is the bigger of the two.",repeat:3},{id:"hercules",name:"The Hercules",species:"Dynastes hercules",plan:"hercules",palette:["#cdbb6a","#8a7a2e","#2a2320","#efe3ae"],hint:"Turn the shared computer off. Properly off.",where:"The Start menu on the shared desktop, and its shutdown.",fact:"The horn is most of its length and it can carry many times its own weight. Its shell changes from olive to black as humidity rises, which makes it a working hygrometer.",repeat:1},{id:"cicada",name:"The Splendid Cicada",species:"Tosena splendida",plan:"cicada",palette:["#2f4f7a","#1a2b45","#12161c","#e8eef7"],hint:"Turn the captions off and on until somebody notices.",where:"The captions control, three times over.",fact:"Cicadas sing with tymbals, a pair of ribbed membranes they buckle and release hundreds of times a second. They are among the loudest insects on earth and they have no voice at all.",repeat:3},{id:"mantis",name:"The Devil's Flower",species:"Idolomantis diabolica",plan:"mantis",palette:["#8fbf5a","#4d7030","#2c3a1c","#f0f4ec"],hint:"Send a window to the taskbar, and keep doing it.",where:"The minimise button on any window on the shared desktop.",fact:"It spends its life pretending to be a flower and eats what comes to visit. Threatened, it opens the whole display at once, which is a bluff and works.",repeat:3},{id:"leaf",name:"The Walking Leaf",species:"Phyllium giganteum",plan:"leaf",palette:["#7fae3f","#4a6b25","#31421c","#d9e8b8"],hint:"Resize a window. Then resize it again. And again.",where:"Any window edge on the shared desktop.",fact:"It is not shaped like a leaf, it is shaped like a chewed leaf, brown edges and all, and it rocks as it walks so the resemblance holds while the wind is on.",repeat:3},{id:"weevil",name:"The Rainbow Weevil",species:"Pachyrhynchus orbifer",plan:"weevil",palette:["#1b1f24","#0e1114","#0a0c0e","#3fd0d8"],hint:"Close things. Three of them.",where:"The close button on the windows of the shared desktop.",fact:"The spots are photonic crystals with the same internal geometry as an opal. Its shell is so hard that other beetles have evolved to look like it rather than risk being mistaken for edible.",repeat:3},{id:"stag",name:"The Stag Beetle",species:"Lucanus cervus",plan:"stag",palette:["#7a4423","#4a2612","#241209","#c98a52"],hint:"Move the windows around. Yes, you can do that.",where:"Dragging windows on the shared desktop, three times.",fact:"The antlers are mandibles, and they are too weak to bite with. They exist to wrestle other males off branches, which is a use for a jaw that cannot chew.",repeat:3},{id:"ulysses",name:"The Blue Emperor",species:"Papilio ulysses",plan:"swallowtail",palette:["#2f7ff0","#12356e","#0c1016","#8fc4ff"],hint:"The camera control does nothing. Do it anyway, three times.",where:"The camera button, which never asks for a camera.",fact:"The blue is a lattice of tiny scales bending light rather than any pigment, so it flashes on and off as the wing turns. Males will chase a scrap of blue paper across a field.",repeat:3},{id:"chafer",name:"The Rose Chafer",species:"Cetonia aurata",plan:"chafer",palette:["#3fae52","#1d6b2c","#12331a","#eaf6e6"],hint:"That clock is the only honest thing on this desktop. Ask it three times.",where:"The clock in the system tray.",fact:"It flies with its wing cases shut, slipping the flight wings out through a notch at the side, which is why it can take off faster than a beetle its size has any business doing.",repeat:3},{id:"longhorn",name:"The Harlequin",species:"Acrocinus longimanus",plan:"longhorn",palette:["#c96a2a","#7d3a12","#1c1512","#f2e4c8"],hint:"A browser inside a browser. Open three more tabs in it.",where:"The new-tab button in the emulated Chrome.",fact:"The forelegs are longer than the whole body. It uses them to walk around tree trunks the way a climber traverses, and the pattern on the back is different on every individual.",repeat:3}];function i(t){return e.find(a=>a.id===t)}var n=e.length;export{e as a,i as b,n as c};
